import { lazy, Suspense, useState } from "react";
import { ArrowUp, Check, ChevronRight, CirclePause, Copy, FilePlus2, Mic, Paperclip, RotateCcw, Sparkles, ThumbsDown, ThumbsUp, TimerReset, X } from "lucide-react";
import type { AssistantState } from "../data/mock-data";
import { quickActions, tasks } from "../data/mock-data";
import { Button } from "./Button";
const AssistantCore=lazy(()=>import("./AssistantCore"));

export function HomePage(){
 const [state,setState]=useState<AssistantState>("idle"); const [input,setInput]=useState(""); const [message,setMessage]=useState("I’ve prepared a focused plan for this afternoon. Review it before I add anything to your schedule.");
 const send=()=>{if(!input.trim())return;setState("thinking");setMessage("I’m organizing that into a clear draft. Nothing will be changed without your approval.");setInput("");setTimeout(()=>setState("success"),900);setTimeout(()=>setState("idle"),1800)};
 return <div className="home-stage animate-page-in">
  <section className="assistant-zone" aria-labelledby="assistant-title"><div className="assistant-heading"><div><p className="eyebrow">Monday, 28 September · Demo workspace</p><h1 id="assistant-title">Good afternoon, Ryan.</h1><p>What would you like to make progress on?</p></div><span className="state-badge"><span className="status-dot"/>{state==="idle"?"Ready":state}</span></div>
   <div className="core-stage"><Suspense fallback={<div className="assistant-core"><div className="core-fallback"><span/></div></div>}><AssistantCore state={state}/></Suspense><div className="core-caption"><span>47</span><strong>{state==="idle"?"Standing by":state.charAt(0).toUpperCase()+state.slice(1)}</strong><small>Local interface preview</small></div></div>
   <div className="state-controls" aria-label="Assistant state preview">{(["idle","listening","thinking","working"] as AssistantState[]).map(x=><button onClick={()=>setState(x)} className={state===x?"selected":""} key={x}>{x}</button>)}</div>
   <div className="conversation"><div className="message assistant-message"><div className="message-meta"><span>47</span><span>Just now · Demo response</span></div><p>{message}</p><div className="approval-card"><div><span className="approval-icon"><Sparkles size={16}/></span><div><strong>Study plan draft</strong><small>4 topics · 2 focus blocks · no actions taken</small></div></div><Button variant="secondary">Review plan <ChevronRight size={15}/></Button></div><div className="message-actions"><button aria-label="Copy response"><Copy size={14}/></button><button aria-label="Helpful"><ThumbsUp size={14}/></button><button aria-label="Not helpful"><ThumbsDown size={14}/></button><button aria-label="Try again"><RotateCcw size={14}/></button></div></div>
    <div className="composer"><textarea value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();send()}}} rows={2} placeholder="Ask 47 anything…" aria-label="Message 47"/><div className="composer-actions"><div><Button variant="icon" aria-label="Attach a file"><Paperclip size={18}/></Button><Button variant="icon" aria-label="Use voice" onClick={()=>setState("permission")}><Mic size={18}/></Button></div><Button variant="primary" aria-label="Send message" onClick={send}><ArrowUp size={18}/></Button></div></div>
   </div>
  </section>
  <aside className="context-rail" aria-label="Today and active work"><section className="context-section"><div className="section-heading"><div><p className="eyebrow">Today</p><h2>What matters now</h2></div><span>3 open</span></div><div className="priority-list">{tasks.map(t=><div className={`priority-item ${t.done?"is-done":""}`} key={t.id}><span className="task-check">{t.done&&<Check size={13}/>}</span><div><strong>{t.title}</strong><small>{t.meta}</small></div></div>)}</div><div className="mini-metrics"><div><span>Next event</span><strong>42 min</strong></div><div><span>Focus</span><strong>18:24</strong></div></div></section>
   <section className="context-section active-task"><div className="section-heading"><div><p className="eyebrow">Active task</p><h2>Creating a study plan</h2></div><span className="status-pill warning">Approval</span></div><p>Step 2 of 4 · Organizing topics</p><div className="progress-track"><span className="progress-half"/></div><div className="task-detail"><span>Waiting for your approval to add reminders.</span><small>Estimated · Demo</small></div><div className="task-buttons"><Button variant="secondary"><CirclePause size={15}/> Pause</Button><Button variant="ghost"><X size={15}/> Cancel</Button></div></section>
   <section className="quick-section"><div className="section-heading"><div><p className="eyebrow">Quick actions</p><h2>Move something forward</h2></div></div><div className="quick-grid">{quickActions.map((a,i)=><button key={a} onClick={()=>setInput(a)}><span>{i===0?<Sparkles size={17}/>:i===2?<TimerReset size={17}/>:<FilePlus2 size={17}/>}</span>{a}</button>)}</div></section>
  </aside>
 </div>
}
